INSERT INTO vector_store (id, content, metadata) VALUES
('847efeca-15e4-4c63-a5fe-578993af4fe2', '계약기간이 종료되었는데 임대인이 보증금을 돌려주지 않는다고요? 그럴 때는 보증금을 꼭 돌려받을 수 있도록 제도를 이용하세요.내용증명을 보내세요.''내용증명''이란 쉽게 말해 우체국에서 공적 증명을 해주는 거예요. 내가 누군가에게 어떤 서류를 전달할 때 내용증명으로 보내면, 우체국에서는 그 서류가 전달되었는지뿐만 아니라 그 내용까지도 증명해주는 거죠. 간단하지만 생각보다 받는 상대방은 심리적 압박을 받을 수 있어요. 물론 실제 법적인 공방이 오가게 될 때 증거로서 작용할 수도 있죠.''임차권등기명령''을 신청보증금을 반환받지 못한 상황에서 급하게 다음 집으로 이사를 해야 하는 상황을 겪고 있는 분들이 많을 거예요. 이런 경우, 내가 이사를 하더라도 임차권등기명령을 완료해 놓으면 대항력을 유지할 수가 있어요지급명령을 신청이 절차는 전세금 반환 소송으로 들어가기 전 최후의 수단이에요. 전세금 반환 소송에 비해 상대적으로 소요 기간이 짧아서 지급 결정 확정까지 한 달 안에 가능해요. 소요 비용 역시 적기 때문에 경제적으로도 유리해요.쉽게 말해 임차권에 대한 권리와 보증금에 대한 권리가 보호받게 되는 거죠. 더군다나 임차권등기명령은 임대인에게 매우 치명적이라고 해요. 등기부등본 을구에 ''주택임차권''이라는 이름으로 그대로 적히게 되거든요. 그리고 누가 들어오든 이미 ''나''의 보증금에 대한 우선변제권이 설정되어 있어서 임대인이 마음대로 다음 세입자를 입주시키고 나를 무시할 수 없어요. 임차권이 등기부등본에 쓰이면 다음 세입자보다 일단 내 보증금이 우선하여 보호받게 되거든요.', '{"title": "체크리스트 : 임대인이 보증금을 돌려주지 않을 때 대처법", "source": "s020701_계약끝난후보증금미반환.md", "category": "prevention", "chunk_index": 0, "total_chunks": 2, "parent_document_id": "bb8b4fcd-41d7-402e-91c0-8eee2b9dbdf9"}'),
('a8bcd10b-3c57-452d-8f57-0602cd6d79a3', '반대로, 내가 알아보고 있는 집의 등기부등본에 임차권등기명령이 표시되어 있다면? 이미 그 집에 살던 세입자가 여전히 보증금을 돌려받고 있지 못한다는 뜻이니, 계약을 더 신중히 고민해주세요.', '{"title": "체크리스트 : 임대인이 보증금을 돌려주지 않을 때 대처법", "source": "s020701_계약끝난후보증금미반환.md", "category": "prevention", "chunk_index": 1, "total_chunks": 2, "parent_document_id": "bb8b4fcd-41d7-402e-91c0-8eee2b9dbdf9"}'),
('7cdda458-b24b-44df-acc6-4b28ef962460', '보증금 돌려받기 전에 지켜야 할 것세입자의 대항력을 유지해야 보증금을 우선 변제받을 수 있는 효력을 가질 수 있어요. 임대인으로부터 보증금을 돌려받지 않았는데 이사를 가거나 다른 집으로 전입신고를 하면 계약 후 전입신고와 확정일자 발급 등으로 취득한 대항력, 우선변제권을 잃게 돼요.따라서 보증금을 돌려받기 전까지 주택의 점유와 전입신고, 확정일자를 유지해야 해요.', '{"title": "보증금 돌려받고 안전하게 이사 나가기", "source": "s030403_보증금돌려받고이사나가기.md", "category": "prevention", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "bc07de40-71f9-4937-9974-fd63901e2dd9"}'),
('a45a0777-792a-4493-bf3a-d3c3050afee4', '세입자가 임대차 계약이 종료된 후에도 대항력과 우선변제권을 유지하면서 이사(퇴거)할 수 있도록 만들어진 제도예요. 주택의 소재지를 관할하는 법원에서 신청할 수 있어요. 임차권등기는 보증금의 전부나 일부를 받지 못한 경우에도 신청할 수 있어요. 물론 임대인의 동의가 없더라도 임차권등기명령을 신청할 수 있어요. 신청할 때 필요한 서류는 임대차계약일자, 임차보증금액, 전입일자, 점유개시일자 및 주민등록등본 등이에요. 단, 임차권등기명령을 신청하고 바로 다른 곳으로 이사하거나 전출해서는 안 되고 임차권등기가 완료되고 이사나 전출을 해야 보호받을 수 있어요', '{"title": "임차권등기명령", "source": "s030403_보증금돌려받고이사나가기.md", "category": "prevention", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "32bb1525-17d0-4efe-bce1-8404656d5f62"}'),
('eca1f1ec-284e-41c2-b5e1-9fcc6a798f3d', '전세계약기간 종료 후 1개월까지 정당한 사유없이 전세보증금을 돌려받지 못했거나, 전세계약기간 중 전세 목적물에 대해 경매 혹은 공매가 실시되어 전세보증금을 반환받지 못했을 경우! HUG 영업점에 통지하고 사고통지서를 제출합니다.보증채무이행청구서, 보증서, 신분증, 부동산등기부등본, 명도확인서, 퇴거예정확인서 등 필요한 서류를 준비해요. 이때 HUG 홈페이지에서 서식을 참고하세요! (서식: khug.or.kr/hug/web/cs/cl/cscl000004.jsp)HUG에서 이행청구의 적정성을 확인하고 심사결과를 통지합니다.마지막으로 대위변제 증서 등 서류를 제출하고 집을 비워주면(명도) 이행금액을 수령할 수 있습니다.', '{"title": "전세보증금반환보증 보증이행 청구절차 (자세히: khug.or.kr/hug/web/ge/er/geer001100.jsp)", "source": "s030403_보증금돌려받고이사나가기.md", "category": "prevention", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "80c48a0e-11a6-4c57-a031-eea74ebe7ef0"}'),
('0ea0d981-1e89-4d23-b96f-6e17b2308df5', '묵시적갱신계약이 끝나기 6개월 전~2개월 전 사이에 계약 해지의사를 서로 전하지 않으면 주택임대차보호법 제6조에 의해 ''묵시적 갱신''이 이뤄져요. 이게 뭐냐면 임대인이 임대차 계약기간이 끝나기 2개월 전까지 세입자에게 갱신을 거절한다고 통지하지 않았고, 세입자 역시 임대차 계약기간이 끝나기 2개월 전까지 계약종료를 통지하지 않았다면 바로 전 계약과 동일한 조건으로 전세계약이 갱신되는 거예요.반대로, 세입자가 임대차 계약기간이 끝나기 2개월 전까지 통지하지 않은 경우에도 묵시적 갱신은 똑같이 적용됩니다. 2년 계약을 했다면, 묵시적갱신을 통해 총 4년을 살 수 있게 되는 거예요. 계약이 2년 연장되는 거죠. 하지만 세입자가 묵시적 갱신 기간 도중에 이사를 가야 한다면 중도 해지도 가능합니다. 묵시적 갱신 기간에는 임대인이 세입자의 해지 통보를 받고 3개월이 지나면 계약이 종료돼요.계약갱신청구권만약에 계약이 끝나기 6개월 전부터 2개월 전 사이에 임대인이 퇴거를 요구하거나, 아주 높은 보증금 인상을 원한다면 이를 거절할 수 있어요. 계약갱신청구권을 통해서 1번 더 거주할 수 있도록 권리를 주장할 수 있고요. 보증금과 월세의 인상률도 5% 범위 안에서 합의할 수 있어요. 단, 월세를 오랫동안 밀렸거나 몇 가지 법에서 정한 거절 사유가 인정되면 임대인이 나의 계약갱신청구를 거부할 수 있으니 미리 확인해보세요.', '{"title": "계약 갱신 시", "source": "s030402_계약갱신시.md", "category": "prevention", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "8adc6be0-6aae-4f89-b2ac-810687c39002"}'),
('21e3622e-47d6-4e9e-ac86-0e3cc91b51e2', '제정 2013. 8.27개정 2013.11.26개폐정리 2015. 6.30개정 2017. 3.13개정 2017.10.23개정 2017.11.27.개정 2019. 9.27.개폐정리 2020. 7.21.개폐정리 2020.12. 4.개정 2022.12.29.개정 2024. 4.26.', '{"title": "전세보증금반환보증약관", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "4f3f2ca1-7afe-421e-8ded-3e06a2f85a09"}'),
('d16c49cd-a061-42f5-88ff-0269ac1ac8d4', '공사는 보증서에 적힌 보증기간 이내에 되돌려 받지 못한 전세보증금에 한하여 보증금액 한도 내에서 보증책임을 부담합니다.【공사】 주택도시보증공사를 의미합니다. 이하 같습니다. 【전세보증금】 임차인이 임대인에게 지급하고 전세계약 해지 또는 종료시 되돌려 받을 금전으로서 전세계약서에 적힌 금액을 말합니다. 이하 같습니다.', '{"title": "제1조(보증채무의 내용)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "a95f5a78-8583-4f65-8220-a7074df99d5b"}'),
('1586f292-a288-4928-bf69-d7bcce7f09e4', '공사는 다음 각 호의 어느 하나에 해당하는 채무에 대해서는 보증책임을 부담하지 않습니다. 천재지변, 전쟁, 내란, 그 밖에 이와 비슷한 사정으로 주채무자가 전세계약을 이행하지 못하여 발생한 채무 주채무자가 전세보증금 반환의무를 지체하여 발생한 이자 및 지연손해금 주채무자가 실제 거주하지 않는 명목상 임차인 등 정상계약자가 아닌 자에게 부담하는 채무 보증채권자가 보증채무 이행을 위한 청구서류를 제출하지 않거나 협력의무를 이행하지 않는 등 보증채권자에게 책임이 있는 사유로 발생하거나 증가된 채무 보증서 발급 당시의 보증조건과 다르거나 보증조건을 공사의 동의 없이 임의변경하여 발생하거나 증가된 채무 주채무자가 부담하는 필요비ㆍ유익비 상환 등의 채무 우선변제권을 취득한 보증채권자가 우선변제권을 상실(타 주소지 전입신고 등)하여 공사의 주채무자에 대한 구상권 행사에 제한이 있는 경우 보증채권자가 전세계약기간이 만료된 후 주채무자와 체결한 새로운 전세계약에 따른 채무 보증채권자가「주택임대차보호법」제3조 제4항에 따라 임대인의 지위를 승계하지 않는 제3자와 체결한 새로운 전세계약에 따른 채무 전세계약기간이 전세계약의 내용 또는 관계 법령에 따라 갱신 혹은 연장된 이후에 발생한 채무 그 밖에 보증채권자에게 책임이 있는 사유 또는 보증채권자가 권리행사를 게을리함으로써 생긴 손해【주채무자】 임차인과 전세계약을 체결하고 계약해지 또는 종료시 전세보증금을 되돌려주기로 약정한 임대인으로서 보증서에 적힌 주채무자를 말합니다. 이하 같습니다.', '{"title": "제2조(보증이행 대상이 아닌 채무)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 2, "parent_document_id": "42cfb52e-dc6f-4393-8791-57d0674dbd08"}'),
('e23ad1b3-ee8f-4060-aa19-6a49920b668e', '【전세계약】 임대인이 임차인에게 임차목적물을 사용ㆍ수익할 수 있게 하고, 임차인이 그 대가로서 임대인에게 전세보증금을 지급하기로 하는 계약(전세보증금이 있는 월세계약을 포함)을 말합니다. 이하 같습니다. 【보증채권자】 주채무자와 전세계약을 체결하고 전세보증금을 지급한 임차인을 말합니다. 이하 같습니다. 【보증조건】 보증서에 적힌 보증금액, 보증기간, 주채무자, 보증채권자, 전세목적물, 전세보증금, 전세계약기간 및 보증 특기사항 등을 말합니다. 이하 같습니다.', '{"title": "제2조(보증이행 대상이 아닌 채무)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 1, "total_chunks": 2, "parent_document_id": "42cfb52e-dc6f-4393-8791-57d0674dbd08"}'),
('566f6032-1a6d-45be-827e-13be740c4879', '공사는 전세보증금반환보증과 관련하여 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 보증채무의 전부 또는 일부에 대하여 보증책임을 부담하지 않습니다. 보증채권자가 「주택임대차보호법」상의 대항력 또는 우선변제권을 잃은 경우(보증채권자가 주택임차권등기가 완료되기전 거주를 이전하거나 주민등록을 이전하는 경우 등) 보증채권자가 전세목적물을 제3자에 전대한 경우 전세보증금반환채권에 대한 채권양도, 금융기관 담보제공, 제3자로부터의 압류·가압류, 전부·추심명령 등으로 인해 공사에 손해가 발생하거나 발생할 우려가 있는 경우 보증채권자가 제5조(보증채권자의 알릴의무)를 위반해 공사에 손해가 발생하거나 발생할 우려가 있는 경우 보증채권자가 제11조(대위 및 구상)의 협조의무를 위반하여 손해가 발생하거나 발생할 우려가 있는 경우【주택임차권등기】 전세계약이 끝난 후 보증금을 되돌려 받지 못한 경우 임차인이 주택임대차보호법 제3조의3에 따라 전세목적물의 소재지를 관할하는 법원으로부터 임차권등기명령을 받아서 전세목적물에 마치는 등기를 말합니다. 【전대】 보증채권자가 임대인의 동의를 얻어 전세목적물을 전차인에게 재임대하는 것을 말합니다.', '{"title": "제3조(면책사항)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "d1581809-f318-44c0-ae87-8aa0ee705056"}'),
('c49426f3-f3e2-4078-a58e-5b0e6cdcf2de', '공사의 면책범위는 다음 각 호에 따릅니다. 제3조 제1호와 제2호의 경우 전세보증금반환보증책임 전부 제3조 제3호부터 제5호까지의 경우 공사의 전세보증금반환보증책임 중 공사가 손해를 입었거나 손해를 입을 것이 예상되는 금액', '{"title": "제4조(면책범위)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "a4104ead-71db-488f-a8a4-229e06ebb31e"}'),
('69dd6563-f2b0-4076-9bb4-90a419df82cb', '① 주채무자 또는 보증채권자는 다음 각 호의 어느 하나에 해당하는 사유가 발생한 경우에는 1개월 이내에 서면으로 그 내용을 공사에 알려야 합니다. 주채무자 또는 보증채권자가 변경된 경우 주채무자, 보증채권자, 연대보증인의 주소가 변경된 경우 경·공매의 개시결정, 채권신고, 배당요구 등 경·공매 관련사항을 통보받은 경우 보증사고가 발생한 경우 보증사고 사유가 없어진 경우 전세계약이 해지 또는 종료된 경우 그 밖에 공사의 보증채무에 영향을 미치는 사항이 발생한 경우② 공사는 주채무자 또는 보증채권자가 정당한 사유 없이 제1항의 통지를 지연하거나 하지 않음으로써 증가된 채무에 대해서는 보증책임을 부담하지 않습니다.', '{"title": "제5조(보증채권자의 알릴 의무)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "1543e5d9-88ce-4841-9c9d-9bbe9909e8bf"}'),
('03ae71b6-fd38-4905-9bb0-9d71aaccb8ae', '① 보증사고는 아래에 열거된 보증사고사유 중 하나가 발생한 경우를 말합니다. 보증채권자가 전세계약의 해지 또는 종료 후 1개월 이내에 정당한 사유 없이 전세보증금을 되돌려 받지 못한 경우 전세계약 기간 중 전세목적물에 대해 경매 또는 공매가 실시되어 배당 후 보증채권자가 전세보증금을 되돌려 받지 못한 경우② 제1항 제1호의 보증사고에 있어서는 전세계약기간이 갱신(묵시적 갱신을 포함)되지 않은 경우에 한합니다.③ 보증사고가 발생한 이후 공사의 보증이행 없이 해당 사고사유가 없어진 경우(2개 이상의 보증사고 발생시 그 보증사고 사유 전부가 없어진 경우)에는 그 보증사고는 처음부터 발생하지 않은 것으로 봅니다.④ 제1항제1호의 전세계약의 해지 또는 종료는 보증채권자가 주채무자에 대한 내용증명우편 등의 방법으로 입증해야 합니다.【정당한 사유】 제6조제1항제1호의 정당한 사유란 원상복구비용, 미납임대료 및 관리비 등의 정산 합의가 이루어지지 않아 주채무자가 전세보증금을 되돌려 주지 않는 경우를 말합니다. 【묵시적 갱신】 주택임대차보호법 제6조에 따라 임대인은 전세계약 종료 6개월 전부터 2개월(2020.12.10. 전에 체결 또는 갱신된 전세계약의 경우 1개월) 전까지, 임차인은 계약종료 2개월(2020.12.10. 전에 체결 또는 갱신된 전세계약의 경우 1개월) 전까지 갱신거절의 통지를 하여야 하며, 통지를 하지 않은 경우 전 임대차와 동일한 조건으로 다시 임대차계약이 체결된 것으로 보는 것을 말합니다. 【해지】 민법상 약정 및 법정해지를 모두 포함합니다. 다만, 경공매시 배당요구에 따른 해지는 포함되지 않습니다.', '{"title": "제6조(보증사고)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "21793159-714f-4833-a09b-365e832c2b13"}'),
('0df2df67-b5aa-438f-b201-19f80d4b7dc5', '① 보증채권자는「주택임대차보호법」 제3조의3에 따라 주택임차권등기를 마친 후(전세목적물의 경⋅공매에 따라 임차권이 이미 소멸된 경우 또는 전세권을 공사로 이전한 임차인인 경우 제외) 공사에 보증채무의 이행을 청구해야 합니다.② 보증채권자는 공사가 필요한 서류의 제출을 요청하거나 공사가 담보로 설정한 담보물의 교부‧이전등기 등 권리의 실행 등을 위해 필요한 조치를 요청한 때에는 지체 없이 응해야 합니다.③ 보증채권자는 보증사고일로부터 2개월 이내에 공사에 보증채무이행을 청구해야 합니다.', '{"title": "제7조(보증채무 이행청구)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "8a7b9332-5166-458b-86e9-8be9ce49321d"}'),
('42d57619-6176-4a9f-80ac-0741de96583e', '① 보증채권자가 보증채무의 이행을 청구할 경우에는 공사에 다음 각 호의 서류를 제출해야 합니다. 보증채무 이행청구서 신분증 사본 보증서 또는 그 사본(공사가 확인가능한 경우에는 생략할 수 있음) 내용증명우편 등 전세계약이 해지 또는 종료되었음을 증명하는 서류 명도확인서 또는 퇴거예정확인서 배당표 등 전세보증금 중 받지 못한 금액을 증명하는 서류(경·공매시) 계좌입금의뢰서 또는 보증채권자 명의의 통장 사본 공사가 요구하는 그 밖의 서류② 보증채권자는 공사로부터 전세계약과 관계있는 서류사본의 제출을 요청받은 경우에는 이에 응해야 합니다.③ 보증채권자가 제1항에서 제2항까지의 서류 중 일부를 누락해 이행을 청구한 경우 공사는 서면 또는 전자문서로 기한을 정해 서류보완을 요청할 수 있습니다.【전자문서】 문자메시지, 카카오톡, 이메일 등 「전자문서 및 전자거래 기본법」 제2조제1호에 따른 전자문서를 의미함', '{"title": "제8조(보증채무 이행청구시 제출서류)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "0214e756-576e-48c3-baa1-b19e09469469"}'),
('bec51229-5957-4d99-a3d3-e7c2ec5caa8c', '① 보증채권자가 제7조에 따라 보증채무 이행청구를 접수한 경우 공사는 다음 각 호의 사항을 심사하고 보증채무의 전부 또는 일부를 이행합니다. 전세목적물에 대한 권리관계 전세목적물에 대한 점유상황 전세목적물에 대한 원상복구비용 주장, 전세보증금이 있는 월세계약의 경우 연체임차료 주장 등 주채무자의 보증채권자에 대한 항변권 또는 보증채무 이행에 대한 이의제기 여부 약관에 따른 면책사항 해당여부 그 밖에 이행심사에 필요한 사항② 공사는 제7조에 따른 보증채권자의 보증채무 이행청구 접수일로부터 1개월 이내(제8조제3항에 따른 공사의 보완 요청이 있는 경우 요청일부터 보증채권자의 보완 완료일까지 기간은 이행기간에 포함되지 않음)에 이행을 위한 심사를 마친 후 보증채권자의 전세목적물 명도와 동시에 보증금액을 지급합니다.③ 공사는 제7조의 보증채무 이행청구 접수 후 주채무자가 이의제기 하거나 보증채권자를 주채무자로 하는 보증사고가 접수되는 등 보증채무의 이행이 적절하지 않다고 판단하는 경우에는 보증채무의 전부 또는 일부의 이행을 거절하거나 유보합니다.④ 제1항의 심사를 제2항의 기한 이내에 마치지 못하는 경우 공사는 보증채권자에게 그 사유를 알리고 그 조사를 마친 날로부터 7일 이내에 보증채무 이행금액을 지급하거나 보증채권자에게 보증채무 이행 거절 또는 유보결정을 알립니다.', '{"title": "제9조(보증채무의 이행)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 2, "parent_document_id": "c1e42ad7-2f24-43fb-bdc1-67efa009befd"}'),
('06b6271f-d69c-476f-a34f-418036e5c1e6', '⑤ 공사는 제2항 및 제4항의 기한 내에 정당한 사유 없이 보증채무이행금액을 지급하지 않는 경우 그 지체된 날로부터 보증채무 이행금 지급일까지 상사법정이율에 따른 금액을 지연일수에 따라 배상합니다.⑥ 공사가 보증채무를 이행할 경우 보증채권자는 보증채무 이행과 동시에 공사에 다음 각 호의 서류를 제출해야 합니다. 대위변제증서 보증채권자가 제7조에 따라 이행청구를 한 경우 주택임차권등기의 말소에 필요한 서류(주택임차권등기명령취하 및 해제신청서, 위임장, 임차권등기 결정서 원본, 인감증명서 등) (다만, 일부보증의 경우 제외) 공사가 제11조 제2항에 따른 공사의 권리를 보전 또는 행사하는데 필요한 서류(전세계약서 원본 등) 공사가 요구하는 그 밖의 서류⑦ 공사는 제1조의 보증이행 대상금액에서 다음 각 호의 금액을 뺀 금액을 보증채권자에게 지급합니다. 보증채권자가 주채무자에게 부담하는 위약금 미납 임대료, 관리상의 비용(관리비 및 도시가스비 등의 미납금, 보증채권자가 책임질 사유로 전세목적물을 멸실 또는 훼손한 경우 시설물 원상복구비용 등 손해배상금), 그 밖에 보증채권자가 책임질 사유로 발생한 비용⑧ 보증채권자가 공사에 채무가 있는 경우 그 금액은 보증채무 이행금액에서 상계합니다.【정당한 사유】 제9조제5항의 정당한 사유란 임차인 사정에 의한 명도확인 지연, 임대인의 이의제기, 본조 제4항에 따른 심사연장 등 공사가 보증채무이행금을 지급하지 않을 사유가 있는 경우를 말합니다.', '{"title": "제9조(보증채무의 이행)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 1, "total_chunks": 2, "parent_document_id": "c1e42ad7-2f24-43fb-bdc1-67efa009befd"}'),
('469c115a-137c-4576-be70-54c55d4502e8', '① 보증채권자는 보증이행금을 받음과 동시에 주채무자에게 전세목적물을 명도해야 합니다.② 보증채권자가 제1항의 명도의무를 이행하지 않은 경우 보증채권자는 공사로부터 받은 보증이행금을 공사에 되돌려 주어야 합니다.③ 보증채권자는 보증이행심사를 마친 날로부터 3개월 이내에 전세목적물을 명도하여야 합니다.', '{"title": "제10조(전세목적물의 명도책임)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "12eef458-cbd2-428f-8d6f-9c51c243b2de"}'),
('4bf58d76-f544-4b65-9541-c1317c80c5bb', '① 공사가 보증채권자에게 보증채무를 이행한 경우에는 공사는 주채무자에게 구상권을 가지며, 보증채권자가 주채무자에게 가지는 권리를 대위해 가집니다.② 보증채권자는 공사에 제1항의 권리를 보전하거나 행사하는데 필요한 서류를 제출해야 하고, 공사로부터 필요 조치를 요청받은 경우에는 지체 없이 응해야 합니다. 또한, 공사는 보증채무의 이행전이라도 서류제출 및 조치를 요구할 수 있습니다.③ 보증채권자는 공사가 보증채무를 이행하기 전이라도 전세목적물의 경매, 주채무자에 대한 「채무자 회생 및 파산에 관한 법률」에 따른 파산 또는 회생절차 및 그 밖에 이와 유사한 절차 등에 따른 배당요구, 채권신고 그 밖에 필요한 방법으로 전세보증금반환채권을 보전 또는 행사해야 하고, 공사가 구상채권을 보전할 수 있도록 협조해야 합니다.④ 공사는 보증채권자가 정당한 사유 없이 제2항 또는 제3항을 위반한 경우에는 그 위반으로 인해 제1항의 권리를 행사하지 못하게 된 금액을 보증채권자에게 청구할 수 있습니다.', '{"title": "제11조(대위 및 구상)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "4e05d6a1-da1b-4f52-a089-87ca9c99e622"}'),
('e6662e3e-dec8-4557-bc1e-b22e5f1a57f4', '① 공사의 보증채무는 공사가 보증서를 발급한 때부터 약관이 정한 바에 따라 유효하게 성립합니다.② 공사는 보증조건에 적합하게 체결된 전세계약에 따른 주채무자의 전세보증금 반환의무에 대하여 보증서에 적힌 내용과 약관이 정한 바에 따라 보증책임을 부담합니다.', '{"title": "제12조(보증채무의 성립 및 책임)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "1fbe8b73-2d19-4526-bded-6ae677aac10e"}'),
('b890f107-e3bc-4e05-a68b-be0d7362b184', '① 주채무자 및 보증채권자는 공사로부터 서면 동의를 받지 않고는 보증조건을 변경할 수 없습니다.② 보증조건의 변경은 공사가 변경사항을 주채무자 및 보증채권자에게 서면으로 알리거나 보증서의 보증조건을 정정하여 재발급한 경우에만 성립합니다.【보증조건】 보증서에 적힌 보증금액, 보증기간, 주채무자, 보증채권자, 전세목적물, 전세보증금, 전세계약기간 및 보증 특기사항 등을 말합니다. 이하 같습니다.', '{"title": "제13조(보증조건의 변경 제한)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "8e6120ee-35b5-4ff1-8791-cb1e39ba8426"}'),
('9b7a32ff-6ca0-4e2c-b99d-10143e3dba50', '① 공사는 주채무자, 보증채권자 또는 대리인이 사기 또는 허위로 전세계약을 체결했거나 이를 근거로 보증을 신청한 경우에는 보증을 취소할 수 있으며, 보증채무 이행을 신청한 경우에는 보증채무 이행을 거절합니다.② 제1항에 따라 보증을 취소하는 경우에는 사기행위와 관련된 제1항의 자는 보증이용이 제한되며 경우에 따라 형사책임을 질 수 있습니다.【사기 또는 허위】 공사가 수사 개시 결정 통지를 받은 경우 등 사기 혐의가 확인되는 경우, 실제와 다른 전세계약(보증요건 충족 또는 대출 목적의 이면계약 체결 등 포함)으로 공사를 기망하여 재산상의 이익을 얻는 경우 등을 말합니다.', '{"title": "제14조(사기행위에 대한 특례)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "077329b2-dcc4-4656-bd00-110b06c22ab8"}'),
('45430080-975a-4122-bb71-e5001533ca17', '① 공사가 지급한 보증채무 이행금이 이 약관에 따른 보증이행 대상이 아닌 채무로 추후 확인될 경우 보증채권자는 그 해당금액 및 법적조치 비용 등을 공사에 되돌려주어야 합니다.② 보증채권자가 공사 및 주채무자로부터 이중으로 변제받은 경우 보증채권자는 즉시 공사로부터 받은 금액을 공사에 되돌려주어야 합니다.', '{"title": "제15조(부당이득 반환)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "0da88351-a771-4545-bf69-02a0f1841d93"}'),
('1a35db9e-5b8a-43ed-8499-fdd6791547ea', '① 보증서는 공사의 서면 동의 없이는 양도 또는 질권설정을 할 수 없으며, 보증목적 이외의 용도로 사용한 경우 공사는 보증책임 또는 특약보증책임을 부담하지 않습니다.② 제1항에 따른 보증채권의 양도를 공사가 서면 동의한 경우 보증과 관련한 권리와 의무를 모두 양도한 것으로 합니다.', '{"title": "제16조(양도 및 질권설정 금지)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "866a6e16-f833-441d-91e2-db52119be50d"}'),
('bacb17c5-0f79-4f07-87b6-0c2e94b6b7e9', '보증채무의 이행장소는 공사의 관할영업부서 또는 소관부서로 합니다.', '{"title": "제17조(보증채무의 이행장소)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "bff80ac3-fa87-4161-be39-bff1f6e5f1f5"}'),
('2edec9b1-67f1-4ff8-9520-7e6851bde2e0', '보증채권자는 보증서를 분실․도난 또는 멸실한 경우에는 즉시 공사에 신고해야 합니다. 신고하지 않음으로써 일어나는 모든 사고에 대해 공사는 책임을 부담하지 않습니다.', '{"title": "제18조(분실․도난 등)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "e4ed5f37-f800-45f4-beee-5a32f12ffbf5"}'),
('b0a0ef14-ac65-495d-a285-d56e0faeca55', '보증에 관한 소송은 피고 소재지 법원을 관할법원(다만, 공사가 피고인 경우에는 공사의 영업부서 또는 본사 소재지 관할법원으로 함)으로 하되, 보증채권자 또는 특약보증채권자와 공사 간에 별도의 합의가 있는 경우에는 그에 따르며, 약관에서 정하지 않은 사항은 대한민국법령에 따릅니다.', '{"title": "제19조(관할법원 및 준거법)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "9979ca60-d32d-439b-8a58-32aba95a62a9"}'),
('93bfe0e6-633e-4570-a94b-8770fe69343f', '① 공사는 신의성실의 원칙에 따라 공정하게 약관을 해석해야 하며 보증채권자에 따라 다르게 해석하지 않습니다.② 공사는 약관의 뜻이 명백하지 않은 경우에는 보증채권자에게 유리하게 해석합니다.③ 공사는 이행하지 않는 채무 등 보증채권자에게 불리하거나 부담을 주는 내용은 확대해 해석하지 않습니다.', '{"title": "제20조(약관의 해석)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "a800db46-fdd3-4afd-9fca-fc8d4e85c085"}'),
('8c1b4b4b-d722-47cc-a969-dfbe00ad0371', '① 공사는 보증의 유지, 관리, 보증이행 및 대위권 행사를 위해 (신용)정보주체의 동의를 받아 개인(신용)정보를 수집, 이용, 조회 또는 제공할 수 있습니다. 다만, 공사는 「개인정보 보호법」,「신용정보의 이용 및 보호에 관한 법률」 등 관계 법령이 정하는 바에 따라, 아래 각호의 경우에는 (신용)정보주체의 동의를 받지 않고 개인(신용)정보를 수집, 이용, 조회 또는 제공할 수 있습니다. 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위해 불가피한 경우 법령 등에서 정하는 소관 업무의 수행을 위하여 불가피한 경우 (신용)정보주체와의 계약의 체결 및 이행을 위하여 불가피하게 필요한 경우 (신용)정보주체 또는 그 법정대리인이 의사표시를 할 수 없는 상태에 있거나 주소불명 등으로 사전 동의를 받을 수 없는 경우로서 명백히 (신용)정보주체 또는 제3자의 급박한 생명, 신체, 재산의 이익을 위하여 필요하다고 인정되는 경우 개인정보처리자(신용정보제공ㆍ이용자)의 정당한 이익을 달성하기 위하여 필요한 경우로서 명백하게 (신용)정보주체의 권리보다 우선하는 경우. 이 경우 개인정보처리자(신용정보제공ㆍ이용자)의 정당한 이익과 상당한 관련이 있고 합리적인 범위를 넘지 않는 경우에 한한다.② 공사는 보증과 관련된 개인정보를 안전하게 관리해야 합니다.부 칙<2020.12. 4.>이 규정은 2020년 12월 10일부터 시행한다.부 칙<2022.12.29.>이 약관은 2022년 12월 30일부터 시행한다.부 칙<2024. 4.26.>이 약관은 2024년 5월 3일부터 시행한다.', '{"title": "제21조(개인정보보호)", "source": "전세보증금반환보증약관.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "e9713d20-cac3-4322-a96e-3f4330aa136b"}'),
('958333d9-6b88-417c-a4df-9be90993a493', '보증금액: 전세보증금반환보증: 보증신청인이 신청한 금액 전세자금대출특약보증: 전세대출금에 보증비율*을 곱한 금액 * 수도권 및 규제지역 : 80%, 그 외 지역 : 90% 보증기간: 대출실행일로부터 대출원금 상환 기일까지 상품분류: 개인보증 / 거주·관리', '{"title": "전세금안심대출보증", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "e579ac23-4854-436e-a37c-fe542b3782fa"}'),
('6f03888a-7d4c-4f14-86e7-cf03b263904f', '전세자금 대출과 전세보증금 보호를 둘 다 받고 싶은 세입자 기존 전세자금 대출을 전세보증금 반환까지 보장되는 대출로 바꾸고 싶어하는 세입자 치솟는 전세금 때문에 전세자금 대출을 최대한 많이 받고 싶은 세입자 전세자금 대출이 필요하나 신용등급이 낮아서 필요한 만큼 대출을 받지 못하는 세입자 상품개요 이용절차 및 제출서류 자주하는 질문 약관 및 상담연락처 임차인에게 전세보증금반환(전세보증금반환보증)과 금융기관에 전세자금대출의 원리금 상환(전세자금대출특약보증)을 함께 책임지는 보증상품 보증서 발급 시 임대인 협조사항 : 임대인은 채권양도통지서를 수령(통지형)하거나, 채권양도승낙서에 동의(승낙형)하여야 하며, 전세계약 사실 등을 유선통화를 통해 확인할 수 있어야 합니다', '{"title": "이런 분들께 추천합니다!", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 0, "total_chunks": 1, "parent_document_id": "13df9bbf-6fc5-4980-947f-7d5c78fdc463"}'),
('5951df50-5e66-4350-be65-bb485705a491', '(자세한 내용은 대출취급 금융기관 및 주택도시보증공사 콜센터에 문의)| 대출취급 금융기관 / (‘21.12월 기준) | 신한은행, 국민은행, 우리은행, NH농협은행, KEB하나은행, 부산은행, 기업은행, 수협은행 | |---|---| | 보증신청 기한 | 전세계약을 체결한 날로부터 다음 아래의 기한 이내 신규 전세계약인 경우: 전세계약서상의 잔금지급일과 전입신고일 중 빠른 날로부터 3개월 이내 갱신 전세계약인 경우: 갱신계약을 체결한 날(월세를 전세로 전환한 경우에는 전환일)로부터 3개월 이내 | | 보증대상 주택유형 | 대상주택 : 단독 ·다중 · 다가구, 연립 · 다세대, 아파트, 주거용 오피스텔 / * 공관, 가정어린이집, 공동생활가정, 지역아동센터, 노인복지시설은 보증대상이 아님 | | 보증채권자 | 전세자금을 대출하는 금융기관 | | 주채무자 | 전세계약을 체결한 임차인으로서 전세자금대출을 받은 차주 (만 19세 이상의 자연인) | | 보증금액 | 전세보증금반환보증: (보증한도 이내에서)보증신청인이 신청한 금액 전세자금대출특약보증: 전세대출금에 보증비율(수도권 및 규제지역 80%, 그 외 지역 90%)을 곱한 금액 | | 보증기간 | 보증부대출 실행일 ~ 대출원금의 상환기일(전세계약기간 만료일 후 1개월) | | 보증한도 | 주택별 보증한도 다음 중 적은 금액에 보증비율(수도권 및 규제지역 80%, 그 외 지역 90%)을 곱한 금액 전세보증금의 80% 이내(신혼부부, 청년가구, 배당이의 소송당사자 가구 90%) / * 보증부 월세계약(전세보증금이 있는 월세계약)인 경우 보증기간 전체에 해당하는 월세 합계액을 차감', '{"title": "보증상품 개요", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 0, "total_chunks": 5, "parent_document_id": "95f2c727-f4e8-4fe2-a3a8-0ebf2d03f3e9"}'),
('5c7d338e-8c6b-4a47-ab73-6d28b36e12c2', '전세보증금반환보증금액의 80%(신혼부부, 청년가구, 배당이의 소송당사자 가구 90%) / 수도권 4억원, 그 외 지역 3.2억원 / (신혼부부, 청년가구, 배당이의 소송당사자 가구는 수도권 4.5억원, 그 외 지역 3.6억원) / / 연간 인정소득 대비 연간 부담하는 이자비용이 40% 이내인 보증부대출예정금액 / / - 전세보증금반환보증금액 한도 / ※ 갱신하는 전세계약으로 전세보증금이 증가하지 않은 경우, 주택가격을 다시 반영하여 보증한도 심사를 하지 않습니다. ■ 주택가격 x 담보인정비율(90%) – 선순위채권 등 / / ■ 선순위채권이 주택가액의 60% 이내일 것 / * 주택가액 = 주택가격*담보인정비율 / / (단독,다가구,다중주택의 경우 타 세입자들의 선순위보증금(후순위, 공실의 최우선변제금 포함)과 선순위채권의 합이 주택가액의 80%이내일 것) / / *선순위채권 :전세보증금보다 우선변제권이 인정되는 담보채권. / 다만. 단독, 다중, 다가구 주택의 경우에는 보증신청인보다 우선하는 선순위 전세보증금(후순위, 공실의 최우선변제금 포함)의 합계를 포함 / *신혼부부 : 연소득 6천만원 이하, 혼인기간 7년 이내인 경우(3개월 이내 결혼 예정자 포함) / *청년가구 : 연소득 5천만원 이하(배우자 포함), 만 19세 이상 34세 이하인 가구 / *배당이의 소송 당사자 가구 : 직전 임대차계약에서 피보증인 또는 배우자가 배당이의 소송 당사자가 된 가구.', '{"title": "보증상품 개요", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 1, "total_chunks": 5, "parent_document_id": "95f2c727-f4e8-4fe2-a3a8-0ebf2d03f3e9"}'),
('2bbd519a-d023-4925-b6cf-a30c1aec9891', '단, 직전 임대차계약 및 현재 임대차계약상 주택임대차보호법 시행령 제11조 우선변제를 받을 임차인의 범위에 해당하고 피보증인 연소득이 40백만원 (배우자포함 60백만원) 이하인 경우 보증신청인(배우자포함) 1주택자인 경우 2억원을 초과할수 없음 | | 보증조건 | 주택의 인도와 전입신고를 마치고 전세계약서상 확정일자를 갖출 것 보증대상 주택의 건물과 토지는 모두 동일 임대인의 소유일 것(공공택지로서 지적미정리로 대지권 미등기인 경우 보증가능) 보증대상 주택 소유권에 대한 권리침해 (경매신청, 압류, 가압류, 가처분 및 가등기 등)가 없을 것 전입세대확인서 상 타 세대의 전입내역이 없을 것 (단독, 다중, 다가구 제외) 전세권이 설정된 경우 이를 공사로 이전하거나 말소 건축물대장에 위반건축물로 기재되어 있지 않을 것 전세계약기간이 1년 이상일 것 전세보증금(보증부 월세계약의 경우 전월세전환율 적용 전세보증금) 수도권 7억원 이하, 그 외 지역 5억원 이하 공인중개사가 확인(날인)한 전세계약 ■ 전세보증금과 선순위채권을 더한 금액이 ‘주택가격 x 담보인정비율(90%)’ 이내일 것 / / Ex) 주택가격 1억원인 경우 / 전세보증금 9천5백만원 ▶ 가입불가 (보증한도 9천만원) / 전세보증금 9천만원 ▶가입가능 (보증한도 9천만원) / 전세보증금 4천만원. 선순위채권 5천5백만원 ▶ 가입불가 (보증한도 3천5백만원, 선순위채권 주택가액 60% 초과) / / ■ [단독.다중.', '{"title": "보증상품 개요", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 2, "total_chunks": 5, "parent_document_id": "95f2c727-f4e8-4fe2-a3a8-0ebf2d03f3e9"}'),
('84b7140b-1ec7-46fc-ade1-cba6452a842d', '다가구의 경우] 임대인 또는 공인중개업자가 확인한 타전세계약 확인서 미제출시 / ＊ 전세보증금 ≤ 주택가격 x 담보인정비율(90%) x (임차인 점유면적 ÷ 건물연면적) / - 선순위채권 등 / | | 유의사항 | 대출을 받은 임차인은 대출실행일 당일에 임차주택 주소지로 전입신고를 마친 후 주민등록등본을 은행으로 제출 대출취급 금융기관의 대출심사기준과 공사의 보증업무 처리 기준에 따라 대출여부 및 대출한도(보증한도)가 결정 대출금리, 대출금의 상환 또는 이자납입이 지연된 경우의 연체이율 등은 고객과 대출취급 금융기관이 약정한 내용에 따름 신용거래 정보가 부족하거나 신용하락의 요인이 될 수 있는 경력(연체 경험 등)이 있을 경우 대출취급이 제한 될 수 있음 전세금 안심대출보증(임차인용)은 임대인이 법인인 경우 취급이 불가능 / / ''18.9.13, ''19.12.16, ''20.6.17 대책 등에 따라 주택보유자는 전세자금대출이 제한될 수 있음 2주택자는 대출보증 취급 불가 ''20.7.', '{"title": "보증상품 개요", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 3, "total_chunks": 5, "parent_document_id": "95f2c727-f4e8-4fe2-a3a8-0ebf2d03f3e9"}'),
('9bbe6f3e-2c97-4388-ada1-78417de48e41', '10 이후 투기지역, 투기과열지구 내 3억원 초과 아파트 구입(규제대상 아파트 구입자)시 대출보증 취급불가 / *실수요자 확인되는 경우에는 규제대상 아파트 구입자임에도 불구하고 예외적으로 보증허용 보증요건에 부합하더라도 취급 금융기관의 대출 심사에 따라 대출이 거절될 수 있음 / ※ 전세 실수요자 요건 및 증빙 / * 대출 실행 후 1개월 이내 본인과 가족의 전입 확인을 위하여 보증대상 목적물과 보유주택에 대한 전입증빙자료(같은 날에 발급한 주민등록등본)를 제출하여야 함 / * 증빙자료는 보증신청일 기준 1개월 이내 발급분으로 보증신청시 제출 / || 예외사유 | 주요 내용 | 증빙자료 | |---|---|---| | 직장이전 | 취업, 이직, 지방 발령 등 | 인사발령문 등 재직기관이 발급한 증빙서류 | | 자녀교육 | 자녀가 타지역 학교 진학 | 재학증명서, 합격통지서 등 | | 질병치료 | 1년 이상 치료나 요양이 필요한 경우 | 의사 소견서 등 | | 부모봉양* | 60세 이상의 부모를 봉양하기 위해 부모와 동일한 지역 에 거주 | 주민등록등본 / 가족관계증명서 | | 학교폭력 | 학교폭력으로 인한 전학 | 징계처분서 등 |', '{"title": "보증상품 개요", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 4, "total_chunks": 5, "parent_document_id": "95f2c727-f4e8-4fe2-a3a8-0ebf2d03f3e9"}'),
('b53c4903-2770-4471-b74c-eb72a0b178ae', '전세보증금반환보증의 아파트 및 오피스텔의 경우 주택가격 산정기준: 가격정보 순서, 산정기준으로 구성됨 적용순위 가격정보 (상기 산정기준 순서대로 적용) ① KB시세 ( onland.kbstar.com ) 한국부동산원 부동산테크 시세 ( www.rtech.or.kr ) 상기 2가지 산정기준 중 선택 적용 (상한가·하한가의 산술평균 적용, 아파트 최저층, 주거용 오피스텔은 하한가 적용) ② 「부동산가격공시 및 감정평가에 관한 법률」에 따라 국토교통부장관이 공시하는 주택가격(오피스텔의 경우 「소득세법」제99조 제1항 제1호 다목에 따라 국세청장이 공시하는 가격)의 140%에 해당하는 금액 아파트 공시가격 확인 : 부동산공시가격 알리미 ( www.realtyprice.kr ) 에서 공동주택공시가격 열람 오피스텔 공시가격 확인 : 국세청 홈택스 ( www.hometax.go.kr ) 에서 상업용건물, 오피스텔 기준시가 조회 ③ 안심전세 앱 시세의 하한가 ④ 해당세대의 등기부등본상 1년 이내의 최근 매매 거래가액 ⑤ 분양가격의 90% (단, 준공 후 1년이 지나지 않은 주택에 한함) ⑥ 토지 공시지가와 건물 시가표준액을 합산하여 전체 연면적 대비 해당세대 연면적 비율로 산출한 금액의 140%에 해당하는 금액 공시가격 확인 : 부동산공시가격 알리미 ( www.realtyprice.kr ) 에서 개별 공시지가 – 개별공시지가x등기부상 토지면적 건물 시가표준액 확인 : 유선으로 관할지자체(구청 등) 해당과(세무과 등)에 확인 또는 임대인으로부터 취득세납부확인서 징구 ※ 주택가격은 보증승인일 현재의 ‘가격정보 순서’로 적용| 적용순위 | 가격정보 (상기 산정기준 순서대로 적용) | |---|---| | ① | KB시세 ( onland.kbstar.', '{"title": "가. 아파트 및 오피스텔 (보증신청인이 임차인인 경우)", "source": "전세금안심대출보증_상품개요.md", "category": "product", "chunk_index": 0, "total_chunks": 2, "parent_document_id": "d91d1f73-2709-425f-8cce-825ec51d0eb9"}'),
